<?php
require_once __DIR__.'/../auth.php';require_admin();
if(($_GET['export']??'')==='requests'){
    $rows=$pdo->query("SELECT product_title,email,status,requested_at FROM restock_notifications ORDER BY requested_at DESC")->fetchAll(PDO::FETCH_ASSOC);
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="stok-gelince-haber-ver.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Ürün','E-posta','Durum','Talep tarihi'],';');foreach($rows as $row)fputcsv($out,$row,';');fclose($out);exit;
}
$moves=$pdo->query('SELECT product_title,change_qty,stock_before,stock_after,movement_type,reference_id,note,created_at FROM stock_movements ORDER BY id DESC LIMIT 300')->fetchAll();
$requests=$pdo->query('SELECT product_title,email,status,requested_at FROM restock_notifications ORDER BY requested_at DESC LIMIT 300')->fetchAll();
$settings=$pdo->query("SELECT setting_value FROM store_settings WHERE setting_key='low_stock_threshold'")->fetchColumn();$threshold=(int)($settings?:5);
$low=$pdo->prepare('SELECT id,title,stock_qty FROM products WHERE stock_qty IS NOT NULL AND stock_qty<=:limit ORDER BY stock_qty ASC,title');$low->execute(['limit'=>$threshold]);$lowRows=$low->fetchAll();
$pageTitle='Stok & talepler';$current='stock';require __DIR__.'/../header.php';
?>
<div class="page-heading"><div><p class="eyebrow">ENVANTER</p><h1>Stok & talepler</h1><p class="text-secondary">Stok hareketleri, azalan ürünler ve müşteri talepleri. E-posta gönderimi henüz yapılmaz.</p></div><a class="btn btn-outline-primary" href="<?=e(app_url('admin/stock/index.php?export=requests'))?>">Talepleri CSV indir</a></div>
<div class="content-card mb-4"><div class="card-heading"><div><h2>Azalan stok uyarıları</h2><p>Stok eşiği: <?= $threshold ?> adet</p></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Ürün</th><th>Mevcut stok</th><th>İşlem</th></tr></thead><tbody><?php foreach($lowRows as $p):?><tr><td><?=e($p['title'])?></td><td><span class="badge text-bg-warning"><?=(int)$p['stock_qty']?> adet</span></td><td><a href="<?=e(app_url('admin/products/edit.php?id='.(int)$p['id']))?>">Stoku düzenle</a></td></tr><?php endforeach;?><?php if(!$lowRows):?><tr><td colspan="3">Azalan stokta ürün bulunmuyor.</td></tr><?php endif;?></tbody></table></div></div>
<div class="content-card mb-4"><div class="card-heading"><div><h2>Stok gelince haber ver talepleri</h2><p><?=count($requests)?> kayıt gösteriliyor. Mail servisi eklendiğinde bekleyen adresler burada hazır olacak.</p></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Ürün</th><th>E-posta</th><th>Durum</th><th>Talep tarihi</th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><?=e($r['product_title'])?></td><td><?=e($r['email'])?></td><td><?=e($r['status']==='pending'?'Bekliyor':$r['status'])?></td><td><?=e(date('d.m.Y H:i',strtotime($r['requested_at'])))?></td></tr><?php endforeach;?><?php if(!$requests):?><tr><td colspan="4">Henüz bildirim talebi yok.</td></tr><?php endif;?></tbody></table></div></div>
<div class="content-card"><div class="card-heading"><div><h2>Son stok hareketleri</h2><p>En son 300 hareket</p></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Tarih</th><th>Ürün</th><th>Hareket</th><th>Önce</th><th>Sonra</th><th>Açıklama</th></tr></thead><tbody><?php foreach($moves as $m):?><tr><td><?=e(date('d.m.Y H:i',strtotime($m['created_at'])))?></td><td><?=e($m['product_title'])?></td><td class="<?=$m['change_qty']<0?'text-danger':'text-success'?>"><?=$m['change_qty']>0?'+':''?><?=(int)$m['change_qty']?></td><td><?= $m['stock_before']===null?'—':(int)$m['stock_before']?></td><td><?= $m['stock_after']===null?'Takip kapalı':(int)$m['stock_after']?></td><td><?=e($m['note'])?></td></tr><?php endforeach;?><?php if(!$moves):?><tr><td colspan="6">Henüz stok hareketi yok.</td></tr><?php endif;?></tbody></table></div></div>
<?php require __DIR__.'/../footer.php';?>
